"""Value Objects for Patient Monitoring Domain"""

from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import List, Optional

from .enums import RegionCategory, TimeframeUnit


@dataclass(frozen=True)
class PatientIdentifier:
	"""Patient identification value object"""
	patient_id: str

	def __post_init__(self):
		if not self.patient_id or not self.patient_id.strip():
			raise ValueError("Patient ID cannot be empty")

	@property
	def value(self) -> str:
		"""Get patient ID value for backward compatibility"""
		return self.patient_id


@dataclass(frozen=True)
class TimeInterval:
	"""Time interval between measurements"""
	start_date: datetime
	end_date: datetime
	duration_months: float

	def __post_init__(self):
		if self.end_date <= self.start_date:
			raise ValueError("End date must be after start date")
		if self.duration_months <= 0:
			raise ValueError("Duration must be positive")

	@property
	def value(self) -> float:
		"""Get duration value in months for backward compatibility"""
		return self.duration_months

	@property
	def unit(self) -> 'TimeframeUnit':
		"""Get time unit for backward compatibility"""
		from .enums import TimeframeUnit
		return TimeframeUnit.MONTHS

	def to_months(self) -> float:
		"""Convert interval to months"""
		return self.duration_months

	def to_years(self) -> float:
		"""Convert interval to years"""
		return self.duration_months / 12

	def to_days(self) -> float:
		"""Convert interval to days"""
		return self.duration_months * 30.44


@dataclass(frozen=True)
class BrainRegion:
	"""Brain region specification"""
	code: str
	name: str
	category: RegionCategory
	parent_region: Optional[str] = None

	def __post_init__(self):
		if not self.code or not self.name:
			raise ValueError("Region code and name are required")


