"""Lightweight, package-local async cache utilities (no external deps).

This module provides a minimal pluggable cache abstraction so the keycloak
package does NOT depend on the host project's caching layer. It offers:

1. In-memory TTL cache (default) – good for single-process usage/tests.
2. Optional Redis backend autodiscovery if `redis.asyncio` is installed and
   KEYCLOAK_REDIS_URL env var is set (format: redis://host:port/0).
3. Ability for a host application to inject a custom backend via
   `set_cache_backend(backend)` where backend implements the three async
   methods defined in `CacheBackendProtocol`.

The JWKS validator will benefit from cross-request caching without forcing
project-specific imports like `src.core.utils.cache`.

If Redis is unavailable or any error occurs during Redis operations, the
system gracefully falls back to the in-memory cache to avoid auth outages.
"""

from __future__ import annotations

import importlib.util
import json
import os
import time
from typing import Any, Protocol

import structlog

logger = structlog.get_logger(__name__)


class CacheBackendProtocol(Protocol):
    async def get_json(self, key: str) -> Any: ...
    async def set_json(self, key: str, value: Any, ttl_seconds: int) -> None: ...
    async def delete(self, key: str) -> None: ...


class InMemoryTTLCache(CacheBackendProtocol):
    def __init__(self):
        # key -> (expiry_epoch_seconds, json_string)
        self._store: dict[str, tuple[float, str]] = {}

    async def get_json(self, key: str) -> Any:
        item = self._store.get(key)
        if not item:
            return None
        expires, data = item
        if expires < time.time():
            self._store.pop(key, None)
            return None
        try:
            return json.loads(data)
        except Exception:
            # Corrupted entry – remove silently
            self._store.pop(key, None)
            return None

    async def set_json(self, key: str, value: Any, ttl_seconds: int) -> None:
        try:
            payload = json.dumps(value)
        except Exception as exc:
            logger.warning("Failed to serialize value for cache", key=key, error=str(exc))
            return
        self._store[key] = (time.time() + max(1, ttl_seconds), payload)

    async def delete(self, key: str) -> None:
        self._store.pop(key, None)


class RedisCache(CacheBackendProtocol):
    def __init__(self, url: str):
        redis_spec = importlib.util.find_spec("redis.asyncio")
        if redis_spec is None:
            raise RuntimeError("redis.asyncio not installed; can't use RedisCache")
        import redis.asyncio as redis  # type: ignore

        self._redis = redis.from_url(url, encoding="utf-8", decode_responses=True)

    async def get_json(self, key: str) -> Any:
        try:
            raw = await self._redis.get(key)
            if raw is None:
                return None
            return json.loads(raw)
        except Exception as exc:
            logger.warning("Redis cache get failed; falling back", key=key, error=str(exc))
            return None

    async def set_json(self, key: str, value: Any, ttl_seconds: int) -> None:
        try:
            payload = json.dumps(value)
            await self._redis.set(key, payload, ex=ttl_seconds)
        except Exception as exc:
            logger.warning("Redis cache set failed", key=key, error=str(exc))

    async def delete(self, key: str) -> None:
        try:
            await self._redis.delete(key)
        except Exception as exc:
            logger.warning("Redis cache delete failed", key=key, error=str(exc))


_backend: CacheBackendProtocol


def _init_backend() -> CacheBackendProtocol:
    url = os.getenv("KEYCLOAK_REDIS_URL") or os.getenv("REDIS_URL")
    if url:
        try:
            logger.info("Initializing Redis cache backend for keycloak", url=url)
            return RedisCache(url)
        except Exception as exc:
            logger.warning("Redis backend init failed; using in-memory cache", error=str(exc))
    logger.info("Using in-memory cache backend for keycloak")
    return InMemoryTTLCache()


_backend = _init_backend()


def set_cache_backend(backend: CacheBackendProtocol) -> None:
    """Allow host application to inject a custom cache backend at runtime."""
    global _backend
    _backend = backend
    logger.info("Custom keycloak cache backend installed", backend=backend.__class__.__name__)


async def cache_get_json(key: str):
    return await _backend.get_json(key)


async def cache_set_json(key: str, value: Any, ttl_seconds: int) -> None:
    await _backend.set_json(key, value, ttl_seconds)


async def cache_delete(key: str) -> None:
    await _backend.delete(key)

