/* Death monitoring function */
void *monitor_philosophers(void *data)
{
    t_table *table = (t_table *)data;
    int i;

    while (!table->simulation_stop)
    {
        i = -1;
        while (++i < table->nb_philos)
        {
            pthread_mutex_lock(&table->philos[i].meal_mutex);
            if (get_time() - table->philos[i].last_meal_time > table->time_to_die)
            {
                print_status(table, i, "died", RED);
                table->simulation_stop = 1;
                pthread_mutex_unlock(&table->philos[i].meal_mutex);
                return NULL;
            }
            pthread_mutex_unlock(&table->philos[i].meal_mutex);
        }
        usleep(1000); // Small sleep to avoid high CPU usage
    }
    return NULL;
}

/* Philosopher routine */
void *philosopher_routine(void *arg)
{
    t_philo *philo = (t_philo *)arg;
    t_table *table = philo->table;

    if (philo->id % 2 == 0)
        usleep(1000); // Even philosophers wait to break symmetry

    while (!table->simulation_stop)
    {
        if (take_forks(philo))
        {
            eat(philo);
            if (philo->meals_eaten == table->nb_must_eat)
                table->philos_full++;
            release_forks(philo);
            print_status(table, philo->id, "is sleeping", BLUE);
            precise_sleep(table->time_to_sleep);
            print_status(table, philo->id, "is thinking", GREEN);
        }
    }
    return NULL;
}

void ft_fill_point(char *point, t_map *map, int x, int y)
{
    char **tab;

    map->map_coords[x][y].x = (float)x;
    map->map_coords[x][y].y = (float)y;
    if (ft_strchr(point, ','))
    {
        tab = ft_split(point, ',');
        map->map_coords[x][y].z = (float)ft_atoi(tab[0]);
        map->map_coords[x][y].color = ft_atoi_base(tab[1], HEXADECIMAL_BASE);
        ft_free_tab(tab);
    }
    else
    {
        map->map_coords[x][y].z = (float)ft_atoi(point);
        map->map_coords[x][y].color = -1;
    }
    if (map->map_coords[x][y].z > map->mx_h)
        map->mx_h = map->map_coords[x][y].z;
    if (map->map_coords[x][y].z < map->mn_h)
        map->mn_h = map->map_coords[x][y].z;
}

void rotate_z(t_segmnt *segmnt, double angle)
{
    t_p new_start;
    t_p new_end;

    new_start.x = segmnt->start.x * cos(angle) - segmnt->start.y * sin(angle);
    new_start.y = segmnt->start.x * sin(angle) + segmnt->start.y * cos(angle);
    segmnt->start.x = new_start.x;
    segmnt->start.y = new_start.y;
    new_end.x = segmnt->end.x * cos(angle) - segmnt->end.y * sin(angle);
    new_end.y = segmnt->end.x * sin(angle) + segmnt->end.y * cos(angle);
    segmnt->end.x = new_end.x;
    segmnt->end.y = new_end.y;
}

void bresenham(t_main_fdf *ptr, t_p start, t_p end)
{
    float x_step;
    float y_step;
    int max_steps;
    int i;
    t_color *color;

    x_step = end.x - start.x;
    y_step = end.y - start.y;
    max_steps = (int)ft_max(ft_abs(x_step), ft_abs(y_step));
    x_step /= max_steps;
    y_step /= max_steps;
    color = color_init(start, end);
    if (!color)
        ft_error("init color");
    i = 0;
    while (i < max_steps)
    {
        start.color = get_color(color, i++, max_steps);
        if (start.x > 0 && start.y > 0 && start.x < ptr->res_x && start.y < ptr->res_y)
            pixel_to_image(ptr->image, start.x, start.y, start.color);
        start.x += x_step;
        start.y += y_step;
    }
    free(color);
}

static void isometric(t_segmnt *segmnt)
{
    t_p new_start;
    t_p new_end;

    new_start.x = (segmnt->start.x - segmnt->start.y) * cos(ANG_30);
    new_start.y = (segmnt->start.x + segmnt->start.y) * sin(ANG_30) - segmnt->start.z;
    segmnt->start.x = new_start.x;
    segmnt->start.y = new_start.y;
    new_end.x = (segmnt->end.x - segmnt->end.y) * cos(ANG_30);
    new_end.y = (segmnt->end.x + segmnt->end.y) * sin(ANG_30) - segmnt->end.z;
    segmnt->end.x = new_end.x;
    segmnt->end.y = new_end.y;
}

void move(t_main *ptr)
{
    t_args_list *tmp;
    int         a_cost;
    int         b_cost;
    int         cheapest;

    tmp = ptr->head_b;
    cheapest = INT_MAX;
    while (tmp)
    {
        if (ft_abs(tmp->a_cost) + ft_abs(tmp->b_cost) < ft_abs(cheapest))
        {
            cheapest = ft_abs(tmp->a_cost) + ft_abs(tmp->b_cost);
            a_cost = tmp->a_cost;
            b_cost = tmp->b_cost;
        }
        tmp = tmp->next;
    }
    rotate_and_push(a_cost, b_cost);
}

int target(t_args_list *lst, int b_index, int t_index, int t_pos)
{
    t_args_list *tmp;

    tmp = lst;
    while (tmp)
    {
        if (tmp->index > b_index && tmp->index < t_index)
        {
            t_index = tmp->index;
            t_pos = tmp->pos;
        }
        tmp = tmp->next;
    }
    if (t_index != INT_MAX)
        return (t_pos);
    tmp = lst;
    while (tmp)
    {
        if (tmp->index < t_index)
        {
            t_index = tmp->index;
            t_pos = tmp->pos;
        }
        tmp = tmp->next;
    }
    return (t_pos);
}

void calculate_cost(t_main *ptr)
{
    t_args_list *tmp;

    tmp = ptr->head_b;
    while (tmp)
    {
        tmp->b_cost = tmp->pos;
        if (tmp->pos > ptr->nb_b / 2)
            tmp->b_cost = (ptr->nb_b - tmp->pos) * -1;
        tmp->a_cost = tmp->target_pos;
        if (tmp->target_pos > ptr->nb_a / 2)
            tmp->a_cost = (ptr->nb_a - tmp->target_pos) * -1;
        tmp = tmp->next;
    }
}

static void rotate_both(int *a_cost, int *b_cost)
{
    while (*a_cost > 0 && *b_cost > 0)
    {
        (*a_cost)--;
        (*b_cost)--;
        ft_rotate("rr");
    }
}

static void r_rotate_both(int *a_cost, int *b_cost)
{
    while (*a_cost < 0 && *b_cost < 0)
    {
        (*a_cost)++;
        (*b_cost)++;
        ft_r_rotate("rrr");
    }
}

