Message::Message(std::string raw_message)
{
	Extractor	_cache(raw_message);
	prefixe	= parse_prefixe(_cache);
	command	= parse_command(_cache);
	params	= parse_params(_cache);
}

t_prefixe	Message::parse_prefixe(Extractor &str)
{
	t_prefixe			output;
	t_available_string	_substr;

	if (str.size() < 2 || str[0] != ':')
		return (output);
	if (str[1] == ' ')
		throw std::runtime_error("Bad prefix format");
	str.erase(0, 1);

	_substr = str.extract_to(" ");
	if (!_substr)
		return (output);
	Extractor substr(_substr());
	output().host = substr.extract_from("@");
	output().user = substr.extract_from("!");
	if (output().host || output().user)
		output().pseudo(substr.str());
	if (output().pseudo)
		output().server_name(substr.str());

	if (!output().host)
		output().host("localhost");
	return (output);
}

void	Monitorer::treatEventListener(IQueue::IEventListener* listener)
{
	user = dynamic_cast<User*>(listener);
	if (user == NULL)
		throw std::runtime_error("Bad EventListener");
	while (user->read_message(&request))
	{
		t_cmd_map::iterator	it = _cmd.find(request->command.name);
		if (it != _cmd.end())
			(this->*(it->second))();
		else
			cmd_unknown();
		delete request;
	}
}

bool	Queue::event_loop(ICrud& crud)
{
	int	num_events;

	num_events = epoll_wait(_epoll_instance, _events_list, _max_events, 0);
	if (num_events < 0)
		throw std::runtime_error("The event loop abort");
	for (int i = 0; i < num_events; i++)
	{
		IQueue::IEventListener* listener = (IQueue::IEventListener*)_events_list[i].data.ptr;
		if (listener->is_alive() == false)
		{
			listener->write();
			crud.removeEventListener(listener);
			continue ;
		}
		if (_events_list[i].events & EPOLLIN)
			listener->read();
		if (_events_list[i].events & EPOLLOUT)
		{
			crud.treatEventListener(listener);
			listener->write();
		}
	}
	return (true);
}

