void	ft_read(int ac, char **av, pid_t pid)
{
	char	*file;
	char	str[5000];
	int		i;

	if (ac == 2)
	{
		i = 0;
		ft_bzero(str, 5000);
		i = read(STDIN_FILENO, str + i, 4999 - i);
		while (ft_strchri(str + i - 1, '\n') == -1)
			i = read(STDIN_FILENO, str + i, 4999 - i);
		send_bit(str, pid);
	}
	else if (ac == 3)
	{
		file = readfile(av[2]);
		if (file == NULL)
			send_bit(av[2], pid);
		else
		{
			send_bit(file, pid);
			free(file);
		}
	}
}

void	send_bit(char *message, pid_t pid)
{
	static int				i = 8;
	static unsigned char	c;
	static char			*str;
	static pid_t			server_pid;

	if (message)
	{
		str = message;
		server_pid = pid;
		c = *str;
	}
	if (!i)
	{
		i = 8;
		c = *(++str);
		if (!c)
			exchange_completed(server_pid);
	}
	if (c && c >> --i & 0x01)
		kill_check(server_pid, SIGUSR1);
	else if (c)
		kill_check(server_pid, SIGUSR2);
}

void	handler(int sig, siginfo_t *siginfo, void *vide)
{
	static unsigned char	c = 0x00;
	static int			count = 0;
	static pid_t			client_pid = 0;

	(void)vide;
	if (!client_pid)
		client_pid = siginfo->si_pid;
	c |= (sig == SIGUSR1);
	if (++count == 8)
	{
		count = 0;
		if (c == 0x00)
		{
			client_pid = 0;
			return ;
		}
		ft_putchar_fd(c, 1);
		c = 0x00;
		kill_check(client_pid, SIGUSR1);
	}
	else
	{
		c <<= 1;
		kill_check(client_pid, SIGUSR2);
	}
}

