static t_token	identify_token(char *line)
{
	int		i;
	t_token	token;

	token.type = UNDEFINED;
	token.value = NULL;
	if (!line || line[0] == '\0' || line[0] == '#')
		return (token);
	token.value = trim(line);
	if (!token.value)
		return (token);
	i = 0;
	while (i < NUM_TOKEN_TYPES)
	{
		if (strncmp(token.value, g_token_types[i], 
			strlen(g_token_types[i])) == 0)
		{
			token.type = i;
			break ;
		}
		i++;
	}
	return (token);
}

bool	scan_file(t_world *world, char *filename)
{
	int		fd;
	char	*line;
	t_token	token;

	if (!check_file_extension(filename, ".rt"))
		return (print_error("Invalid file extension"));
	fd = open(filename, O_RDONLY);
	if (fd == -1)
		return (print_error("Could not open file"));
	while (get_next_line(fd, &line))
	{
		token = identify_token(line);
		if (token.type != UNDEFINED)
		{
			if (!process_token(world, token))
				return (false);
		}
		free(token.value);
		free(line);
	}
	close(fd);
	return (post_process_world(world));
}

static void	set_pixel_size(t_camera *camera)
{
	float	half_view;
	float	aspect;

	half_view = tanf(camera->field_of_view / 2);
	aspect = camera->hsize / camera->vsize;
	if (aspect >= 1)
	{
		camera->half_width = half_view;
		camera->half_height = half_view / aspect;
	}
	else
	{
		camera->half_width = half_view * aspect;
		camera->half_height = half_view;
	}
	camera->pixel_size = (camera->half_width * 2) / camera->hsize;
}

t_camera	*camera(int hsize, int vsize, float field_of_view)
{
	t_camera	*cam;

	cam = malloc(sizeof(t_camera));
	if (!cam)
		return (NULL);
	cam->hsize = hsize;
	cam->vsize = vsize;
	cam->field_of_view = field_of_view;
	cam->transform = identity_matrix();
	cam->inverse = identity_matrix();
	set_pixel_size(cam);
	return (cam);
}

t_tuple	lighting(t_material material, t_light *light, t_comp comp, bool in_shadow)
{
	t_tuple	effective_color;
	t_tuple	ambient;
	t_tuple	diffuse;
	t_tuple	specular;
	t_tuple	lightv;
	t_tuple	reflectv;
	float	light_dot_normal;
	float	reflect_dot_eye;
	float	factor;

	// Combine surface color with light color
	effective_color = hadamard(get_color_at(material, comp.point), light->intensity);
	// Calculate the ambient contribution
	ambient = scalar(effective_color, material.ambient);
	if (in_shadow)
		return (ambient);
	// Calculate direction to light source
	lightv = normalize(subtract(light->position, comp.point));
	// Determine if light is on correct side
	light_dot_normal = dot(lightv, comp.normalv);
	if (light_dot_normal < 0)
	{
		diffuse = color(0, 0, 0);
		specular = color(0, 0, 0);
	}
	else
	{
		// Calculate diffuse contribution
		diffuse = scalar(effective_color, material.diffuse * light_dot_normal);
		// Calculate specular contribution
		reflectv = reflect(negate(lightv), comp.normalv);
		reflect_dot_eye = dot(reflectv, comp.eyev);
		if (reflect_dot_eye <= 0)
			specular = color(0, 0, 0);
		else
		{
			factor = powf(reflect_dot_eye, material.shininess);
			specular = scalar(light->intensity, material.specular * factor);
		}
	}
	return (add(ambient, add(diffuse, specular)));
}

t_ray	*ray_for_pixel(t_camera *camera, int px, int py)
{
	float	xoffset;
	float	yoffset;
	float	world_x;
	float	world_y;
	t_tuple	pixel;
	t_tuple	origin;
	t_tuple	direction;
	t_ray	*r;

	// Calculate the offset from the edge of the canvas to the pixel center
	xoffset = (px + 0.5) * camera->pixel_size;
	yoffset = (py + 0.5) * camera->pixel_size;
	// Calculate the world coordinates of the pixel
	world_x = camera->half_width - xoffset;
	world_y = camera->half_height - yoffset;
	// Transform the canvas point and the origin using camera matrix
	pixel = multiply_matrix_tuple(camera->inverse, point(world_x, world_y, -1));
	origin = multiply_matrix_tuple(camera->inverse, point(0, 0, 0));
	// Calculate the ray direction vector and normalize it
	direction = normalize(subtract(pixel, origin));
	// Create the ray
	r = ray(origin, direction);
	return (r);
}

void	render(t_camera *camera, t_world *world, t_canvas *image)
{
	t_ray	*r;
	t_tuple	color_val;
	int	x;
	int	y;

	y = 0;
	while (y < camera->vsize)
	{
		x = 0;
		while (x < camera->hsize)
		{
			// Generate ray through pixel
			r = ray_for_pixel(camera, x, y);
			// Calculate color at intersection
			color_val = color_at(world, r);
			// Set pixel in canvas
			write_pixel(image, x, y, color_val);
			// Clean up ray
			free_ray(r);
			x++;
		}
		y++;
	}
}

bool	is_shadowed(t_world *world, t_tuple point, t_light *light)
{
	t_tuple	v;
	float	distance;
	t_ray	*r;
	t_intersect_list	*intersections;
	t_intersection	*h;

	// Vector from point to light
	v = subtract(light->position, point);
	distance = magnitude(v);
	// Create a ray from point to light
	r = ray(point, normalize(v));
	// Find intersections between point and light
	intersections = intersect_world(world, r);
	// Check if any intersection blocks the light
	h = hit(intersections);
	// Free resources
	free_ray(r);
	free_intersect_list(intersections);
	// Return true if there's a hit before the light source
	return (h != NULL && h->t < distance);
}

t_matrix	*translation(float x, float y, float z)
{
	t_matrix	*m;

	m = identity_matrix();
	m->data[0][3] = x;
	m->data[1][3] = y;
	m->data[2][3] = z;
	return (m);
}

t_matrix	*scaling(float x, float y, float z)
{
	t_matrix	*m;

	m = identity_matrix();
	m->data[0][0] = x;
	m->data[1][1] = y;
	m->data[2][2] = z;
	return (m);
}

t_matrix	*view_transform(t_tuple from, t_tuple to, t_tuple up)
{
	t_tuple	forward;
	t_tuple	left;
	t_tuple	true_up;
	t_matrix	*orientation;
	t_matrix	*translation_matrix;
	t_matrix	*result;

	forward = normalize(subtract(to, from));
	left = cross(forward, normalize(up));
	true_up = cross(left, forward);
	orientation = identity_matrix();
	orientation->data[0][0] = left.x;
	orientation->data[0][1] = left.y;
	orientation->data[0][2] = left.z;
	orientation->data[1][0] = true_up.x;
	orientation->data[1][1] = true_up.y;
	orientation->data[1][2] = true_up.z;
	orientation->data[2][0] = -forward.x;
	orientation->data[2][1] = -forward.y;
	orientation->data[2][2] = -forward.z;
	translation_matrix = translation(-from.x, -from.y, -from.z);
	result = multiply_matrices(orientation, translation_matrix);
	free_matrix(orientation);
	free_matrix(translation_matrix);
	return (result);
}

static t_discriminant	sphere_discriminant(t_object *obj, t_ray *ray)
{
	t_discriminant	discr;
	t_tuple		sphere_to_ray;

	sphere_to_ray = subtract(ray->origin, obj->origin);
	discr.a = dot(ray->direction, ray->direction);
	discr.b = 2 * dot(ray->direction, sphere_to_ray);
	discr.c = dot(sphere_to_ray, sphere_to_ray) - 1;
	discr.discriminant = discr.b * discr.b - 4 * discr.a * discr.c;
	return (discr);
}

t_intersect_list	*intersect_sphere(t_object *obj, t_ray *ray)
{
	t_ray			transformed_ray;
	t_discriminant	discr;
	t_intersect_list	*xs;
	float			t[2];

	transformed_ray = transform_ray(ray, obj->inverse);
	discr = sphere_discriminant(obj, &transformed_ray);
	if (discr.discriminant < 0)
		return (NULL);
	t[0] = (-discr.b - sqrtf(discr.discriminant)) / (2 * discr.a);
	t[1] = (-discr.b + sqrtf(discr.discriminant)) / (2 * discr.a);
	xs = intersect_list();
	if (!xs)
		return (NULL);
	add_intersection(xs, intersection(t[0], obj));
	add_intersection(xs, intersection(t[1], obj));
	return (xs);
}

