t_cmd *parse_command(t_token *tokens)
{
	t_cmd *command;
	t_token *current;

	if (!tokens)
		return (NULL);

	command = init_cmd();
	if (!command)
		return (NULL);

	current = tokens;
	while (current)
	{
		if (current->type == PIPE)
		{
			command->next = parse_command(current->next);
			break;
		}
		else if (is_redirection(current->type))
		{
			if (!handle_redirection(command, current))
			{
				free_cmd(command);
				return (NULL);
			}
			current = current->next->next; // Skip redirection token and filename
		}
		else // Word token (command or argument)
		{
			add_argument(command, current->value);
			current = current->next;
		}
	}

	return (command);
}

void	handler_sigint(int sig)
{
	(void)sig;
	g_ms_data.exit_status = 128 + SIGINT;
	write(2, "\n", 1);
	rl_replace_line("", 0);
	rl_on_new_line();
	rl_redisplay();
}

void	handler_sigquit(int sig)
{
	(void)sig;
}

int	set_interactive_signals(void)
{
	struct sigaction	sa_int;
	struct sigaction	sa_quit;

	sigemptyset(&sa_int.sa_mask);
	sigemptyset(&sa_quit.sa_mask);
	sa_int.sa_handler = handler_sigint;
	sa_int.sa_flags = 0;
	sa_quit.sa_handler = handler_sigquit;
	sa_quit.sa_flags = 0;
	if (sigaction(SIGINT, &sa_int, NULL) == -1
		|| sigaction(SIGQUIT, &sa_quit, NULL) == -1)
		return (print_error("sigaction", NULL, 1));
	return (0);
}

int	set_noninteractive_signals(void)
{
	signal(SIGINT, SIG_DFL);
	signal(SIGQUIT, SIG_DFL);
	return (0);
}

int	heredoc(t_cmd *cmd, char *delim)
{
	char	*line;
	int		fd[2];

	if (pipe(fd) == -1)
		return (-1);
	while (1)
	{
		line = readline("> ");
		if (!line || !ft_strcmp(line, delim))
		{
			free(line);
			break;
		}
		write(fd[1], line, ft_strlen(line));
		write(fd[1], "\n", 1);
		free(line);
	}
	close(fd[1]);
	if (cmd->input_fd != STDIN_FILENO)
		close(cmd->input_fd);
	cmd->input_fd = fd[0];
	return (0);
}

t_token *tokenize_input(char *input)
{
	t_token *tokens;
	int i;
	int j;

	tokens = NULL;
	i = 0;
	while (input[i])
	{
		if (is_whitespace(input[i]))
			i++;
		else if (is_operator(input[i]))
		{
			j = get_operator_length(&input[i]);
			add_token(&tokens, create_token(input + i, j, get_token_type(input + i, j)));
			i += j;
		}
		else
		{
			j = get_word_length(&input[i]);
			add_token(&tokens, create_token(input + i, j, WORD));
			i += j;
		}
	}
	return (tokens);
}

int	execute_command(t_cmd *cmd)
{
	int	type;
	int	status;
	pid_t	pid;

	type = check_builtin(cmd);
	if (is_parent_builtin(type) && !cmd->next && cmd->prev == NULL)
		return (execute_builtin(cmd, type));

	signal(SIGINT, SIG_IGN);
	signal(SIGQUIT, SIG_IGN);
	pid = fork();
	if (pid == -1)
		return (print_error("fork", NULL, 1));
	if (pid == 0)
	{
		signal(SIGINT, SIG_DFL);
		signal(SIGQUIT, SIG_DFL);
		process_redirections(cmd);
		if (cmd->prev)
			dup2(cmd->prev->pipe_fd[0], STDIN_FILENO);
		if (cmd->next)
			dup2(cmd->pipe_fd[1], STDOUT_FILENO);
		close_pipes(cmd);
		if (type)
			exit(execute_builtin(cmd, type));
		else if (cmd->path)
			execve(cmd->path, cmd->cmd_array, get_env_array());
		exit(127);
	}
	if (cmd->prev)
		close(cmd->prev->pipe_fd[0]);
	if (cmd->next)
		close(cmd->pipe_fd[1]);
	waitpid(pid, &status, 0);
	return (WEXITSTATUS(status));
}

int	process_redirections(t_cmd *cmd)
{
	int	i;

	i = -1;
	if (cmd->input_fd != STDIN_FILENO)
	{
		if (dup2(cmd->input_fd, STDIN_FILENO) == -1)
			return (print_error("dup2", NULL, 1));
		close(cmd->input_fd);
	}
	if (cmd->output_fd != STDOUT_FILENO)
	{
		if (dup2(cmd->output_fd, STDOUT_FILENO) == -1)
			return (print_error("dup2", NULL, 1));
		close(cmd->output_fd);
	}
	while (cmd->fds && cmd->fds[++i] > 2)
		close(cmd->fds[i]);
	return (0);
}

int	open_input_file(t_cmd *cmd, char *file)
{
	int	fd;

	fd = open(file, O_RDONLY);
	if (fd == -1)
		return (print_error(file, NULL, 1));
	if (cmd->input_fd != STDIN_FILENO)
		close(cmd->input_fd);
	cmd->input_fd = fd;
	cmd->fds = add_fd(cmd->fds, fd);
	return (0);
}

int	open_output_file(t_cmd *cmd, char *file, int append)
{
	int	fd;
	int	flags;

	flags = O_WRONLY | O_CREAT;
	if (append)
		flags |= O_APPEND;
	else
		flags |= O_TRUNC;
	fd = open(file, flags, 0644);
	if (fd == -1)
		return (print_error(file, NULL, 1));
	if (cmd->output_fd != STDOUT_FILENO)
		close(cmd->output_fd);
	cmd->output_fd = fd;
	cmd->fds = add_fd(cmd->fds, fd);
	return (0);
}

int	check_builtin(t_cmd *cmd)
{
	int			i;
	size_t		z;
	static char	tab[7][7] = {"echo", "exit", "cd", "export",
		"unset", "env", "pwd"};

	i = -1;
	if (!cmd || cmd->cmd_array == NULL)
		return (0);
	if ((cmd->cmd_array && ft_strchr(*cmd->cmd_array, '/'))
		|| (cmd->path && ft_strchr(cmd->path, '/')))
		return (0);
	while (++i < 7)
	{
		z = ft_strlen(*cmd->cmd_array);
		if (ft_strlen(tab[i]) > z)
			z = ft_strlen(tab[i]);
		if (!ft_strncmp(*cmd->cmd_array, tab[i], z))
			return (i + 1);
	}
	return (0);
}

int	execute_builtin(t_cmd *cmd, int type)
{
	int	i;

	i = 0;
	if (type == 1)
		i = ft_echo(cmd);
	else if (type == 2)
		i = ft_exit(cmd);
	else if (type == 3)
		i = ft_cd(cmd);
	else if (type == 4)
		i = ft_export(cmd);
	else if (type == 5)
		i = ft_unset(cmd);
	else if (type == 6)
		i = ft_env(cmd);
	else if (type == 7)
		i = ft_pwd(cmd);
	return (i);
}

t_env	*create_env_node(char *key, char *value)
{
	t_env	*node;

	node = malloc(sizeof(t_env));
	if (!node)
		return (NULL);
	node->key = ft_strdup(key);
	if (!node->key)
	{
		free(node);
		return (NULL);
	}
	node->value = NULL;
	if (value)
	{
		node->value = ft_strdup(value);
		if (!node->value)
		{
			free(node->key);
			free(node);
			return (NULL);
		}
	}
	node->next = NULL;
	return (node);
}

void	env_add(t_env **env_list, char *key, char *value)
{
	t_env	*node;
	t_env	*current;

	if (!env_list || !key)
		return ;
	if (*env_list)
	{
		current = find_env(*env_list, key);
		if (current)
		{
			if (current->value)
				free(current->value);
			current->value = value ? ft_strdup(value) : NULL;
			return ;
		}
	}
	node = create_env_node(key, value);
	if (!node)
		return ;
	if (!*env_list)
		*env_list = node;
	else
	{
		current = *env_list;
		while (current->next)
			current = current->next;
		current->next = node;
	}
}

