export class GameState {
  constructor(canvas, settings) {
    this.canvas = canvas;
    this.settings = settings;
    this.leftPaddle = { x: 0, y: (canvas.height - settings.paddleHeight) / 2, width: settings.paddleWidth, height: settings.paddleHeight };
    this.rightPaddle = { x: canvas.width - settings.paddleWidth, y: (canvas.height - settings.paddleHeight) / 2, width: settings.paddleWidth, height: settings.paddleHeight };
    this.ball = { x: canvas.width / 2, y: canvas.height / 2, radius: settings.ballRadius, velocityX: 0, velocityY: 0 };
    this.leftScore = 0;
    this.rightScore = 0;
    this.gameOver = false;
    this.paused = false;
    this.maxScore = settings.maxScore || 5;
    this.deltaTime = 0;
    this.lastTime = Date.now();
  }

  reset() {
    // Reset game state
    this.leftPaddle.y = (this.canvas.height - this.settings.paddleHeight) / 2;
    this.rightPaddle.y = (this.canvas.height - this.settings.paddleHeight) / 2;
    this.ball.x = this.canvas.width / 2;
    this.ball.y = this.canvas.height / 2;
    this.ball.velocityX = Math.random() < 0.5 ? -this.settings.ballSpeed : this.settings.ballSpeed;
    this.ball.velocityY = Math.random() * 2 - 1; // Random vertical speed
    this.gameOver = false;
    this.paused = false;

    // Reset scores
    this.leftScore = 0;
    this.rightScore = 0;
  }

  update() {
    if (this.paused || this.gameOver) return;

    const now = Date.now();
    const elapsedTime = now - this.lastTime;

    // Update delta time for smooth movement
    if (elapsedTime > 0) {
      this.deltaTime += elapsedTime / (1000 / 60); // Assuming a target frame rate of 60 FPS
      if (this.deltaTime > 1) this.deltaTime = 1; // Clamp to avoid large jumps
    }

    // Update ball position
    this.ball.x += this.ball.velocityX * this.deltaTime;
    this.ball.y += this.ball.velocityY * this.deltaTime;

    // Check for wall collisions
    if (this.ball.y <= 0 || this.ball.y >= this.canvas.height) {
      this.ball.velocityY *= -1; // Reverse Y velocity on collision
    }

    // Check for paddle collisions
    if (this._checkPaddleCollision(this.leftPaddle) || this._checkPaddleCollision(this.rightPaddle)) {
      this.ball.velocityX *= -1; // Reverse X velocity on collision
    }

    // Check for scoring conditions
    if (this.ball.x < 0) {
      this.rightScore++;
      if (this.rightScore >= this.maxScore) {
        this.gameOver = true;
      } else {
        this.reset();
      }
    } else if (this.ball.x > this.canvas.width) {
      this.leftScore++;
      if (this.leftScore >= this.maxScore) {
        this.gameOver = true;
      } else {
        this.reset();
      }
    }

    // Update last time for next frame
    this.lastTime = now;
  }

  _checkPaddleCollision(paddle) {
    return (
      this.ball.x + this.ball.radius > paddle.x &&
      this.ball.x - this.ball.radius < paddle.x + paddle.width &&
      this.ball.y + this.ball.radius > paddle.y &&
      this.ball.y - this.ball.radius < paddle.y + paddle.height
    );
  }
}

export class AIOpponent {
  constructor(difficulty = 'medium', gameState, settings) {
    this.difficulty = difficulty; // 'easy', 'medium', 'hard'
    this.gameState = gameState;
    this.settings = settings;
    this.paddleHeight = settings.paddleHeight;
    this.canvasHeight = settings.canvasHeight;
    this.reactionDelay = this._getReactionDelay();
    this.lastMoveTime = Date.now();
    this.targetPosition = null;

    // Error margin for hard AI not being perfect
    this.predictionError = this._getPredictionError();

    // For easy AI: randomness in movement
    this.randomFactor = this._getRandomFactor();
    this.lastRandomChange = Date.now();
    this.randomChangeInterval = 500; // Change direction every 500ms for easy AI

    // For medium AI: how far ahead to look
    this.lookAheadFactor = this._getLookAheadFactor();
  }

  _getReactionDelay() {
    // Delay in milliseconds before AI reacts
    switch (this.difficulty) {
      case 'easy': return 300;
      case 'medium': return 150;
      case 'hard': return 30;
      default: return 150;
    }
  }

  _getPredictionError() {
    // Error margin in prediction (pixels)
    switch (this.difficulty) {
      case 'easy': return 60;
      case 'medium': return 20;
      case 'hard': return 5;
      default: return 20;
    }
  }

  _getRandomFactor() {
    // Random movement factor for easy AI
    switch (this.difficulty) {
      case 'easy': return 0.7;
      case 'medium': return 0.3;
      case 'hard': return 0;
      default: return 0.3;
    }
  }

  _getLookAheadFactor() {
    // How far ahead in time the AI predicts (milliseconds)
    switch (this.difficulty) {
      case 'easy': return 100;
      case 'medium': return 500;
      case 'hard': return 1000;
      default: return 500;
    }
  }

  update() {
    const ball = this.gameState.ball;
    let paddleY;

    // Determine which paddle to control based on the ball's direction
    if (ball.velocityX > 0) {
      // Ball is moving toward right paddle
      paddleY = this.gameState.rightPaddle.y;
    } else {
      // Ball is moving toward left paddle
      paddleY = this.gameState.leftPaddle.y;
    }

    const now = Date.now();

    // Easy AI: Add randomness periodically
    if (this.difficulty === 'easy' && now - this.lastRandomChange > this.randomChangeInterval) {
      this.lastRandomChange = now;
      if (Math.random() < this.randomFactor) {
        // Move randomly sometimes
        return Math.random() * this.canvasHeight;
      }
    }

    // Calculate where the ball will intersect with the paddle's x-coordinate
    if (now - this.lastMoveTime > this.reactionDelay) {
      this.lastMoveTime = now;
      this.targetPosition = this._predictBallPosition();

      // Add error based on difficulty
      const error = (Math.random() * 2 - 1) * this.predictionError;
      this.targetPosition = Math.max(0, Math.min(this.canvasHeight - this.paddleHeight, this.targetPosition + error));
    }

    // Return current target position
    return this.targetPosition;
  }

  _predictBallPosition() {
    const ball = this.gameState.ball;
    const paddleX = ball.velocityX > 0 ? this.settings.canvasWidth - this.settings.paddleWidth : this.settings.paddleWidth;

    // If ball is moving away from this paddle, just track the center
    if ((ball.velocityX > 0 && paddleX < ball.x) || (ball.velocityX < 0 && paddleX > ball.x)) {
      return (this.canvasHeight - this.paddleHeight) / 2;
    }

    // Calculate time until ball reaches paddle
    const distanceToTravel = Math.abs(paddleX - ball.x);
    const timeToReach = distanceToTravel / Math.abs(ball.velocityX);

    // Predict position based on difficulty level
    const lookAheadTime = Math.min(timeToReach, this.lookAheadFactor / 1000);

    // Calculate where ball will be after look-ahead time
    let futureY = ball.y + ball.velocityY * lookAheadTime;

    // Account for bounces off top and bottom walls
    const bounceCount = Math.floor(futureY / this.settings.canvasHeight);
    if (bounceCount % 2 === 0) {
      futureY = futureY % this.settings.canvasHeight;
    } else {
      futureY = this.settings.canvasHeight - (futureY % this.settings.canvasHeight);
    }

    // Return position, adjusted to center paddle on ball
    return Math.max(0, Math.min(this.canvasHeight - this.paddleHeight, futureY - this.paddleHeight / 2));
  }

  // Advanced prediction for hard difficulty
  _predictBallPath() {
    if (this.difficulty !== 'hard') return this._predictBallPosition();

    const ball = this.gameState.ball;
    const paddleX = ball.velocityX > 0 ? this.settings.canvasWidth - this.settings.paddleWidth : this.settings.paddleWidth;

    // Clone ball properties to simulate future movement
    let simulatedBall = {
      x: ball.x,
      y: ball.y,
      velocityX: ball.velocityX,
      velocityY: ball.velocityY
    };

    // Simulate ball movement until it reaches paddle X position
    while ((ball.velocityX > 0 && simulatedBall.x < paddleX) || 
           (ball.velocityX < 0 && simulatedBall.x > paddleX)) {
      // Update simulated ball position
      simulatedBall.x += simulatedBall.velocityX * 0.016; // Assuming 60 FPS (16ms)
      simulatedBall.y += simulatedBall.velocityY * 0.016;

      // Check for collision with top/bottom walls
      if (simulatedBall.y <= 0 || simulatedBall.y >= this.settings.canvasHeight) {
        simulatedBall.velocityY *= -1; // Reverse Y velocity on collision
      }
    }

    // Return predicted position, adjusted to center paddle on ball
    return Math.max(0, Math.min(this.canvasHeight - this.paddleHeight, simulatedBall.y - this.paddleHeight / 2));
  }
}

export class GameEngine {
  constructor(gameState, settings) {
    this.state = gameState;
    this.settings = settings;
    this.lastUpdate = Date.now();
  }

  update() {
    const now = Date.now();
    const deltaTime = (now - this.lastUpdate) / 1000; // Convert to seconds
    this.lastUpdate = now;

    // Update ball position
    this.state.ball.x += this.state.ball.velocityX * deltaTime;
    this.state.ball.y += this.state.ball.velocityY * deltaTime;

    // Check for collisions with top and bottom walls
    if (this.state.ball.y <= 0 || this.state.ball.y >= this.settings.canvasHeight) {
      this.state.ball.velocityY = -this.state.ball.velocityY;
      this.state.ball.y = Math.max(0, Math.min(this.state.ball.y, this.settings.canvasHeight));
    }

    // Check for collisions with paddles
    this.checkPaddleCollision();

    // Check for scoring
    this.checkScoring();

    return this.state;
  }

  checkPaddleCollision() {
    // Left paddle collision
    if (this.state.ball.velocityX < 0 &&
        this.state.ball.x <= this.settings.paddleWidth &&
        this.state.ball.y >= this.state.leftPaddle.y &&
        this.state.ball.y <= this.state.leftPaddle.y + this.settings.paddleHeight) {

      // Calculate bounce angle based on where the ball hit the paddle
      const hitPosition = (this.state.ball.y - this.state.leftPaddle.y) / this.settings.paddleHeight;
      const bounceAngle = (hitPosition - 0.5) * Math.PI / 3; // -π/6 to π/6 range

      // Update velocity with increased speed
      const speed = Math.sqrt(Math.pow(this.state.ball.velocityX, 2) + Math.pow(this.state.ball.velocityY, 2));
      const newSpeed = speed * 1.05; // Increase speed by 5%

      this.state.ball.velocityX = Math.cos(bounceAngle) * newSpeed;
      this.state.ball.velocityY = Math.sin(bounceAngle) * newSpeed;
    }

    // Right paddle collision (similar logic)
    if (this.state.ball.velocityX > 0 &&
        this.state.ball.x >= this.settings.canvasWidth - this.settings.paddleWidth &&
        this.state.ball.y >= this.state.rightPaddle.y &&
        this.state.ball.y <= this.state.rightPaddle.y + this.settings.paddleHeight) {

      const hitPosition = (this.state.ball.y - this.state.rightPaddle.y) / this.settings.paddleHeight;
      const bounceAngle = (hitPosition - 0.5) * Math.PI / 3; // -π/6 to π/6 range

      const speed = Math.sqrt(Math.pow(this.state.ball.velocityX, 2) + Math.pow(this.state.ball.velocityY, 2));
      const newSpeed = speed * 1.05; // Increase speed by 5%

      this.state.ball.velocityX = -Math.cos(bounceAngle) * newSpeed;
      this.state.ball.velocityY = Math.sin(bounceAngle) * newSpeed;
    }
  }

  checkScoring() {
    // Ball out of bounds on left side
    if (this.state.ball.x < 0) {
      this.state.scores.right += 1;
      this.resetBall('right');
    }

    // Ball out of bounds on right side
    if (this.state.ball.x > this.settings.canvasWidth) {
      this.state.scores.left += 1;
      this.resetBall('left');
    }
  }

  resetBall(direction) {
    this.state.ball.x = this.settings.canvasWidth / 2;
    this.state.ball.y = this.settings.canvasHeight / 2;

    const angle = ((Math.random() * Math.PI / 4) - Math.PI / 8) + (direction === 'left' ? Math.PI : 0);
    const speed = this.settings.initialBallSpeed;

    this.state.ball.velocityX = Math.cos(angle) * speed;
    this.state.ball.velocityY = Math.sin(angle) * speed;
  }
}

import pyotp
import qrcode
import io
import base64
from django.conf import settings
from django.contrib.auth import get_user_model
from rest_framework import status, viewsets, permissions
from rest_framework.response import Response
from rest_framework.decorators import action
from .models import UserProfile

User = get_user_model()

class TwoFactorAuthViewSet(viewsets.ViewSet):
    permission_classes = [permissions.IsAuthenticated]

    @action(detail=False, methods=['post'])
    def enable(self, request):
        """Enable 2FA for the authenticated user"""
        user = request.user
        profile = UserProfile.objects.get(user=user)

        # Check if 2FA is already enabled
        if profile.two_factor_enabled:
            return Response({'error': '2FA is already enabled'}, 
                            status=status.HTTP_400_BAD_REQUEST)

        # Generate a new secret key
        secret_key = pyotp.random_base32()
        profile.two_factor_secret = secret_key
        profile.save(update_fields=['two_factor_secret'])

        # Generate provisioning URI for QR code
        totp = pyotp.TOTP(secret_key)
        provisioning_uri = totp.provisioning_uri(
            name=user.email,
            issuer_name=settings.TWO_FACTOR_ISSUER
        )

        # Generate QR code image
        qr = qrcode.QRCode(
            version=1,
            error_correction=qrcode.constants.ERROR_CORRECT_L,
            box_size=10,
            border=4,
        )
        qr.add_data(provisioning_uri)
        qr.make(fit=True)

        img = qr.make_image(fill_color="black", back_color="white")
        buffer = io.BytesIO()
        img.save(buffer, format="PNG")
        qr_code_base64 = base64.b64encode(buffer.getvalue()).decode()

        return Response({
            'secret': secret_key,
            'qr_code': f'data:image/png;base64,{qr_code_base64}'
        })

    @action(detail=False, methods=['post'])
    def verify(self, request):
        """Verify and activate 2FA with provided token"""
        user = request.user
        profile = UserProfile.objects.get(user=user)
        token = request.data.get('token')

        if not token:
            return Response({'error': 'Token is required'}, 
                            status=status.HTTP_400_BAD_REQUEST)

        # Verify the token
        totp = pyotp.TOTP(profile.two_factor_secret)
        if totp.verify(token):
            profile.two_factor_enabled = True
            profile.save(update_fields=['two_factor_enabled'])
            return Response({'success': '2FA has been enabled'})
        else:
            return Response({'error': 'Invalid token'}, 
                            status=status.HTTP_400_BAD_REQUEST)

    @action(detail=False, methods=['post'])
    def disable(self, request):
        """Disable 2FA for the authenticated user"""
        user = request.user
        profile = UserProfile.objects.get(user=user)
        token = request.data.get('token')

        # Verify user with current token before disabling
        if not profile.two_factor_enabled:
            return Response({'error': '2FA is not enabled'}, 
                            status=status.HTTP_400_BAD_REQUEST)

        if not token:
            return Response({'error': 'Token is required'}, 
                            status=status.HTTP_400_BAD_REQUEST)

        # Verify the token
        totp = pyotp.TOTP(profile.two_factor_secret)
        if totp.verify(token):
            profile.two_factor_enabled = False
            profile.two_factor_secret = ""
            profile.save(update_fields=['two_factor_enabled', 'two_factor_secret'])
            return Response({'success': '2FA has been disabled'})
        else:
            return Response({'error': 'Invalid token'}, 
                            status=status.HTTP_400_BAD_REQUEST)

    @action(detail=False, methods=['post'])
    def validate(self, request):
        """Validate a token for a user during login"""
        user_id = request.data.get('user_id')
        token = request.data.get('token')

        if not user_id or not token:
            return Response({'error': 'User ID and token are required'}, 
                            status=status.HTTP_400_BAD_REQUEST)

        try:
            user = User.objects.get(id=user_id)
            profile = UserProfile.objects.get(user=user)

            if not profile.two_factor_enabled:
                return Response({'error': '2FA is not enabled for this user'},
                                status=status.HTTP_400_BAD_REQUEST)

            # Verify the token
            totp = pyotp.TOTP(profile.two_factor_secret)
            if totp.verify(token):
                return Response({'success': True})
            else:
                return Response({'error': 'Invalid token'},
                                status=status.HTTP_400_BAD_REQUEST)

        except User.DoesNotExist:
            return Response({'error': 'User not found'},
                            status=status.HTTP_404_NOT_FOUND)
        except UserProfile.DoesNotExist:
            return Response({'error': 'User profile not found'},
                            status=status.HTTP_404_NOT_FOUND)

import json
import asyncio
from channels.generic.websocket import AsyncWebsocketConsumer
from asgiref.sync import sync_to_async
from django.db import transaction
from .models import Game, GamePlayer, User
from .game_engine import GameEngine

class GameConsumer(AsyncWebsocketConsumer):
    async def connect(self):
        self.game_id = self.scope['url_route']['kwargs']['game_id']
        self.game_group_name = f'game_{self.game_id}'
        self.user = self.scope['user']

        # Join game group
        await self.channel_layer.group_add(
            self.game_group_name,
            self.channel_name
        )

        # Accept the connection
        await self.accept()

        # Check if user is a player or spectator
        is_player = await self.is_game_player()
        if is_player:
            await self.send(text_data=json.dumps({
                'type': 'game_joined',
                'role': 'player',
                'player_id': str(self.user.id)
            }))

            # Get or initialize game state
            game_state = await self.get_game_state()
            await self.channel_layer.group_send(
                self.game_group_name,
                {
                    'type': 'game_state_update',
                    'state': game_state
                }
            )
        else:
            await self.send(text_data=json.dumps({
                'type': 'game_joined',
                'role': 'spectator'
            }))

    async def disconnect(self, close_code):
        # Leave game group
        await self.channel_layer.group_discard(
            self.game_group_name,
            self.channel_name
        )

        # Handle player disconnection
        is_player = await self.is_game_player()
        if is_player:
            await self.handle_player_disconnect()

    async def receive(self, text_data):
        data = json.loads(text_data)
        message_type = data.get('type')

        if message_type == 'paddle_move':
            # Validate user is a player
            is_player = await self.is_game_player()
            if not is_player:
                return

            # Update paddle position
            position = data.get('position')
            await self.update_paddle_position(position)

            # Broadcast the updated position
            await self.channel_layer.group_send(
                self.game_group_name,
                {
                    'type': 'paddle_position',
                    'player_id': str(self.user.id),
                    'position': position
                }
            )

        elif message_type == 'start_game':
            # Only host can start game
            is_host = await self.is_game_host()
            if is_host:
                await self.start_game()

    async def game_state_update(self, event):
        # Send game state to the client
        await self.send(text_data=json.dumps({
            'type': 'game_state',
            'state': event['state']
        }))

    async def paddle_position(self, event):
        # Send paddle position update to clients
        await self.send(text_data=json.dumps({
            'type': 'paddle_position',
            'player_id': event['player_id'],
            'position': event['position']
        }))

    @sync_to_async
    def is_game_player(self):
        try:
            return GamePlayer.objects.filter(game_id=self.game_id, user=self.user).exists()
        except Exception:
            return False

    @sync_to_async
    def is_game_host(self):
        try:
            return Game.objects.filter(id=self.game_id, host=self.user).exists()
        except Exception:
            return False

    @sync_to_async
    def get_game_state(self):
        game = Game.objects.get(id=self.game_id)
        # Construct and return game state
        return {
            'id': str(game.id),
            'status': game.status,
            'players': list(game.gameplayer_set.values('user__id', 'user__username', 'side')),
            'scores': {'left': game.score_left, 'right': game.score_right},
            'ball': {'x': game.ball_x, 'y': game.ball_y},
            'leftPaddle': {'y': game.left_paddle_y},
            'rightPaddle': {'y': game.right_paddle_y}
        }

    @sync_to_async
    def update_paddle_position(self, position):
        with transaction.atomic():
            game = Game.objects.get(id=self.game_id)
            player = game.gameplayer_set.get(user=self.user)

            if player.side == 'left':
                game.left_paddle_y = position
            else:
                game.right_paddle_y = position
            game.save(update_fields=['left_paddle_y', 'right_paddle_y'])

    @sync_to_async
    def handle_player_disconnect(self):
        with transaction.atomic():
            game = Game.objects.get(id=self.game_id)
            if game.status == 'playing':
                # Forfeit the game
                game.status = 'finished'
                player = game.gameplayer_set.get(user=self.user)

                if player.side == 'left':
                    game.score_right = game.max_score  # Right player wins
                else:
                    game.score_left = game.max_score  # Left player wins

                game.save()

    async def start_game(self):
        # Initialize and start the game
        game_state = await self.initialize_game()

        # Notify all clients that the game is starting
        await self.channel_layer.group_send(
            self.game_group_name,
            {
                'type': 'game_state_update',
                'state': game_state
            }
        )

        # Start the game loop
        asyncio.create_task(self.game_loop())

    @sync_to_async
    def initialize_game(self):
        with transaction.atomic():
            game = Game.objects.get(id=self.game_id)
            game.status = 'playing'
            game.ball_x = 400  # Center X
            game.ball_y = 300  # Center Y
            game.ball_velocity_x = 200  # Initial X velocity
            game.ball_velocity_y = 0  # Initial Y velocity
            game.save()

            return self.get_game_state_sync(game)

    def get_game_state_sync(self, game):
        # Non-async version for use within @sync_to_async methods
        return {
            'id': str(game.id),
            'status': game.status,
            'players': [{'user_id': p.user.id, 'username': p.user.username, 'side': p.side} 
                       for p in game.gameplayer_set.select_related('user').all()],
            'scores': {'left': game.score_left, 'right': game.score_right},
            'ball': {'x': game.ball_x, 'y': game.ball_y, 
                    'velocityX': game.ball_velocity_x, 'velocityY': game.ball_velocity_y},
            'leftPaddle': {'y': game.left_paddle_y},
            'rightPaddle': {'y': game.right_paddle_y}
        }

    async def game_loop(self):
        # Main game loop, runs until game is finished
        engine = GameEngine()

        while True:
            # Get current game state
            game = await self.get_game_sync()

            if game.status != 'playing':
                break

            # Update game state using physics engine
            game_state = self.get_game_state_sync(game)
            updated_state = engine.update(game_state)

            # Save updated state to database
            await self.save_game_state(updated_state)

            # Broadcast updated state to all clients
            await self.channel_layer.group_send(
                self.game_group_name,
                {
                    'type': 'game_state_update',
                    'state': updated_state
                }
            )

            # Check for win condition
            if updated_state['scores']['left'] >= game.max_score or \
               updated_state['scores']['right'] >= game.max_score:
                await self.end_game()
                break

            # Wait before next update (60 FPS)
            await asyncio.sleep(1/60)

    @sync_to_async
    def get_game_sync(self):
        return Game.objects.get(id=self.game_id)

    @sync_to_async
    def save_game_state(self, state):
        with transaction.atomic():
            game = Game.objects.get(id=self.game_id)
            game.ball_x = state['ball']['x']
            game.ball_y = state['ball']['y']
            game.ball_velocity_x = state['ball']['velocityX']
            game.ball_velocity_y = state['ball']['velocityY']
            game.score_left = state['scores']['left']
            game.score_right = state['scores']['right']
            game.save()

    @sync_to_async
    def end_game(self):
        with transaction.atomic():
            game = Game.objects.get(id=self.game_id)
            game.status = 'finished'
            game.save()

            # Update player stats, ELO, etc.
            self.update_player_stats(game)

    def update_player_stats(self, game):
        # Update player statistics based on game results
        left_player = game.gameplayer_set.get(side='left').user
        right_player = game.gameplayer_set.get(side='right').user

        # Determine winner
        if game.score_left > game.score_right:
            winner = left_player
            loser = right_player
        else:
            winner = right_player
            loser = left_player

        # Update statistics
        winner.profile.games_won += 1
        loser.profile.games_lost += 1
        winner.profile.save()
        loser.profile.save()

